public boolean canArrange(int[] arr, int k) {
    // Handle null array
    if (arr == null) {
        return false;
    }
    int n = arr.length;
    // If array length is odd, cannot form pairs
    if (n % 2 != 0) {
        return false;
    }
    // k must be positive to avoid division by zero
    if (k <= 0) {
        return false;
    }
    // Empty array can trivially be paired
    if (n == 0) {
        return true;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // ensure non-negative remainder
        count[rem]++;
    }
    // Remainder 0 must have even count
    if (count[0] % 2 != 0) {
        return false;
    }
    // Check pairs of remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // occurs when k is even and r == k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[complement]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Validate inputs
    if (n <= 0) {
        throw new IllegalArgumentException("Number of nodes must be positive.");
    }
    if (edges == null) {
        throw new IllegalArgumentException("Edges array cannot be null.");
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple array must have length equal to n.");
    }

    // Build adjacency list
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            throw new IllegalArgumentException("Each edge must contain exactly two nodes.");
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge contains invalid node indices.");
        }
        adj[u].add(v);
        adj[v].add(u);
    }

    // Iterative DFS to compute minimal time
    boolean[] hasAppleInSubtree = new boolean[n];
    int totalTime = 0;
    int[] parent = new int[n];
    Arrays.fill(parent, -1);

    // Stack elements: {node, state}
    // state 0 = first visit, state 1 = post-visit
    Deque<int[]> stack = new ArrayDeque<>();
    stack.push(new int[]{0, 0});

    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0];
        int state = cur[1];

        if (state == 0) {
            // Pre-visit
            stack.push(new int[]{node, 1}); // Post-visit marker
            for (int nei : adj[node]) {
                if (nei == parent[node]) continue;
                parent[nei] = node;
                stack.push(new int[]{nei, 0});
            }
        } else {
            // Post-visit: compute hasAppleInSubtree and accumulate time
            boolean hasAppleHere = hasApple[node];
            for (int nei : adj[node]) {
                if (nei == parent[node]) continue;
                if (hasAppleInSubtree[nei]) {
                    totalTime += 2; // go to child and back
                    hasAppleHere = true;
                }
            }
            hasAppleInSubtree[node] = hasAppleHere;
        }
    }

    return totalTime;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.put(ch, freq.getOrDefault(ch, 0) + 1);
    }
    StringBuilder result = new StringBuilder(n);
    while (result.length() < n) {
        // Ascending phase
        Character next = freq.firstKey();
        if (next == null) {
            break;
        }
        result.append(next);
        decrementOrRemove(freq, next);
        char last = next;
        while (true) {
            Character higher = freq.higherKey(last);
            if (higher == null) {
                break;
            }
            result.append(higher);
            decrementOrRemove(freq, higher);
            last = higher;
        }
        if (result.length() == n) {
            break;
        }
        // Descending phase
        Character largest = freq.lastKey();
        if (largest == null) {
            break;
        }
        result.append(largest);
        decrementOrRemove(freq, largest);
        last = largest;
        while (true) {
            Character lower = freq.lowerKey(last);
            if (lower == null) {
                break;
            }
            result.append(lower);
            decrementOrRemove(freq, lower);
            last = lower;
        }
    }
    return result.toString();
}

private void decrementOrRemove(java.util.TreeMap<Character, Integer> map, Character key) {
    int count = map.get(key);
    if (count <= 1) {
        map.remove(key);
    } else {
        map.put(key, count - 1);
    }
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int total = 0;
    for (int num : nums) {
        total += num;
    }

    // dp[k] holds all possible sums using exactly k elements
    @SuppressWarnings("unchecked")
    List<Set<Integer>> dp = new ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new HashSet<>());
    }
    dp.get(0).add(0);

    for (int num : nums) {
        // iterate k from high to low to avoid using the same element twice
        for (int k = n - 1; k >= 0; k--) {
            if (dp.get(k).isEmpty()) {
                continue;
            }
            for (int sum : dp.get(k)) {
                dp.get(k + 1).add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        long targetLong = (long) total * k;
        if (targetLong % n != 0) {
            continue;
        }
        int target = (int) (targetLong / n);
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input gracefully
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // If there's only one step, the cost to reach the top is that step's cost
    if (n == 1) {
        return cost[0];
    }
    // Use two variables to keep track of the minimal cost to reach the previous two steps
    int prev = cost[0]; // cost to reach step 0
    int curr = cost[1]; // cost to reach step 1
    for (int i = 2; i < n; i++) {
        int next = Math.min(prev, curr) + cost[i];
        prev = curr;
        curr = next;
    }
    // The top can be reached from either of the last two steps
    return Math.min(prev, curr);
}

