}

public boolean hasAllCodes(String s, int k) {
    // Handle null or empty string
    if (s == null) {
        return false;
    }
    // Edge case: k <= 0, only empty string exists
    if (k <= 0) {
        return true;
    }
    int n = s.length();
    // If string is shorter than k, cannot contain all codes
    if (n < k) {
        return false;
    }
    // For small k, use boolean array for speed
    if (k <= 20) {
        int total = 1 << k; // 2^k
        boolean[] seen = new boolean[total];
        int mask = 0;
        int maskLimit = total - 1;
        int count = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c != '0' && c != '1') {
                // Invalid character, treat as failure
                return false;
            }
            mask = ((mask << 1) & maskLimit) | (c - '0');
            if (i >= k - 1) {
                if (!seen[mask]) {
                    seen[mask] = true;
                    count++;
                    if (count == total) {
                        return true;
                    }
                }
            }
        }
        return false;
    } else {
        // For larger k, use a HashSet to avoid huge array
        java.util.Set<Integer> seen = new java.util.HashSet<>();
        long mask = 0L;
        long maskLimit = (1L << k) - 1;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c != '0' && c != '1') {
                return false;
            }
            mask = ((mask << 1) & maskLimit) | (c - '0');
            if (i >= k - 1) {
                seen.add((int)mask);
                // If the set size reaches 2^k, we can stop early
                if (seen.size() == (1L << k)) {
                    return true;
                }
            }
        }
        return false;
    }
}

public int isPrefixOfWord(String sentence, String searchWord) {
