public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxSum = nums[0];
    long minSum = nums[0];
    long currentMax = nums[0];
    long currentMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        currentMax = Math.max(val, currentMax + val);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(val, currentMin + val);
        minSum = Math.min(minSum, currentMin);
    }
    long result = Math.max(maxSum, -minSum);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        long next = (long) fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add((int) next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) return -1;
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) return -1;
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if c and top are same letter but opposite case
            if (Math.abs(c - top) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = new int[1];
    java.util.HashSet<String> used = new java.util.HashSet<>();
    dfs(s, 0, used, max);
    return max[0];
}

private void dfs(String s, int index, java.util.HashSet<String> used, int[] max) {
    if (index == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int len = 1; len <= s.length() - index; len++) {
        String sub = s.substring(index, index + len);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, index + len, used, max);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
