public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            if (((num >> i) & 1) == 1) {
                bitCount++;
            }
        }
        if ((bitCount % 3) == 1) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0) {
        return result;
    }
    if (low < 0) {
        low = 0;
    }
    Queue<Long> queue = new LinkedList<>();
    // Initialize queue with single digit numbers 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        // Do not generate children for 0 to avoid duplicates
        if (num == 0) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long high = n / (factor * 10);
        long cur = (n / factor) % 10;
        long low = n % factor;
        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

