public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    int[][] dpH = new int[m][n];
    int[][] dpV = new int[m][n];
    int[][] dpD = new int[m][n];
    int[][] dpAD = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            return 0; // invalid row length
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                         Math.max(dpD[i][j], dpAD[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpAD[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Use long to safely handle Integer.MIN_VALUE
    long absVal = Math.abs((long) n);
    String numStr = Long.toString(absVal);

    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    if (negative) {
        sb.append('-');
    }

    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 1;
    }
    int n = A.length;
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    java.util.Arrays.sort(A);
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int allMask = (1 << n) - 1;

    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Integer mask, Integer lastIdx) {
            if (mask == allMask) {
                return 1;
            }
            long key = (((long) mask) << 4) | (lastIdx + 1);
            Integer cached = memo.get(key);
            if (cached != null) {
                return cached;
            }
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) {
                    continue; // skip duplicate values at same recursion depth
                }
                if (lastIdx == -1 || isSquare[A[i] + A[lastIdx]]) {
                    count += apply(mask | (1 << i), i);
                }
            }
            memo.put(key, count);
            return count;
        }
    };

    return dfs.apply(0, -1);
}

