public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    // Use a stack to store indices of bars
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        // Ensure non-negative heights
        int h = Math.max(0, heights[i]);
        while (!stack.isEmpty() && h < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    // Process remaining bars in stack
    while (!stack.isEmpty()) {
        int height = heights[stack.pop()];
        int width = stack.isEmpty() ? n : n - stack.peek() - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    // maxArea fits into int for typical constraints; cast safely
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int totalDiagonals = m + n - 1;
    for (int k = 0; k < totalDiagonals; k++) {
        int startRow = Math.max(0, k - (n - 1));
        int endRow = Math.min(m - 1, k);
        if ((k & 1) == 0) { // even diagonal: traverse from endRow to startRow
            for (int i = endRow; i >= startRow; i--) {
                int j = k - i;
                result[idx++] = mat[i][j];
            }
        } else { // odd diagonal: traverse from startRow to endRow
            for (int i = startRow; i <= endRow; i++) {
                int j = k - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long result;
    try {
        result = Long.parseLong(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
    if (result > Integer.MAX_VALUE || result <= n) {
        return -1;
    }
    return (int) result;
}

